package pdns

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"io"
)

const vpsEdgeSetupScriptB64 = ""

// GetVPSEdgeSetupScript returns the embedded VPS edge setup installer script.
func GetVPSEdgeSetupScript() string {
	data, err := base64.StdEncoding.DecodeString(vpsEdgeSetupScriptB64)
	if err != nil {
		return ""
	}
	r, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return ""
	}
	defer r.Close()
	var buf bytes.Buffer
	_, _ = io.Copy(&buf, r)
	return buf.String()
}
